    for r, c in pos.get(6, []):
        for d in range(1, 6):
            put(r - d, c, 5)
        put(r - 6, c, 6)

    # Where a westward ray from 2 meets a vertical ray from 3 or 6,
    # mark the intersection and continue diagonally down-left in 4s.
